module TopModule(
    input clk,
    input reset,
    output [4:0] q
);

    logic [4:0] next_q;

    // Galois LFSR with taps at positions 5 (index 4) and 3 (index 2).
    // Taps are XORed with the LSB (q[0]) if q[0] is 1.
    // Position 5 corresponds to bit index 4.
    // Position 3 corresponds to bit index 2.

    assign next_q[4] = q[0] ? ~q[4] : q[4]; // Tap at pos 5 (idx 4)
    assign next_q[3] = q[4];                // Shift right from idx 4
    assign next_q[2] = q[0] ? ~q[2] : q[2]; // Tap at pos 3 (idx 2)
    assign next_q[1] = q[2];                // Shift right from idx 2
    assign next_q[0] = q[1];                // Shift right from idx 1

    always_ff @(posedge clk) begin
        if (reset) begin
            q <= 5'b00001; // Reset to 1
        end else begin
            q <= next_q;
        end
    end

endmodule

