module TopModule (
    input  clk,
    input  areset,
    input  x,
    output z
);

    logic [1:0] state;
    logic [1:0] next_state;

    parameter S0 = 2'b00;
    parameter S1 = 2'b01;

    always_ff @(posedge clk or posedge areset) begin
        if (areset) begin
            state <= S0;
        end else begin
            state <= next_state;
        end
    end

    always_comb begin
        case (state)
            S0: begin
                if (x == 1'b0) begin
                    next_state = S0;
                end else begin
                    next_state = S1;
                end
            end
            S1: begin
                next_state = S1;
            end
            default: begin
                next_state = S0;
            end
        endcase
    end

    assign z = (state == S1) ? ~x : x;

endmodule

