module TopModule (
    input  c,
    input  d,
    output [3:0] mux_in
);

    // K-map analysis for F(a,b,c,d):
    // ab=00 (mux_in[0]): 
    //   cd=00->0, cd=01->1, cd=11->1, cd=10->1
    //   This is true when NOT(cd=00). i.e., c OR d.
    assign mux_in[0] = c | d;

    // ab=01 (mux_in[1]):
    //   cd=00->0, cd=01->0, cd=11->0, cd=10->0
    //   Always 0.
    assign mux_in[1] = 1'b0;

    // ab=11 (mux_in[2]):
    //   cd=00->0, cd=01->0, cd=11->1, cd=10->0
    //   True only when c=1 and d=1.
    assign mux_in[2] = c & d;

    // ab=10 (mux_in[3]):
    //   cd=00->1, cd=01->0, cd=11->1, cd=10->1
    //   False only when cd=01. i.e., NOT(c=0 AND d=1).
    //   Equivalent to c OR (~d).
    assign mux_in[3] = c | (~d);

endmodule

