    // We need to read the current value. Since PHT is updated on clock edge,
    // reading it in combinational logic gives the value from the previous cycle (or reset).
    // However, the problem states: "If training and prediction of the same PHT entry happen at the same time, 
    // the prediction sees the PHT state before training because training only modifies the PHT at the next positive clock edge."
    // This implies standard synchronous read behavior where the register holds the old value until the clock edge.

    logic [1:0] pred_pht_entry;

    assign pred_pht_entry = pht[pred_index];

    // Predict taken if MSB of counter is 1 (states 2'b10 or 2'b11 are taken)
    assign predict_taken = pred_pht_entry[1];

    // Output the global history used for this prediction
    assign predict_history = ghr;

    // Training Logic
    // Calculate index for training
    wire [6:0] train_index = train_pc ^ train_history;

    // Determine new PHT value based on train_taken
    // Saturating counter update:
    // If taken (1): increment (max 3)
    // If not taken (0): decrement (min 0)
    logic [1:0] new_pht_value;

    always_comb begin
        case (pht[train_index])
