            2'b01: new_pht_value = train_taken ? 2'b10 : 2'b00;
            2'b10: new_pht_value = train_taken ? 2'b11 : 2'b01;
            2'b11: new_pht_value = train_taken ? 2'b11 : 2'b10;
            default: new_pht_value = 2'b00;
        endcase
    end

    // Sequential Logic
    always_ff @(posedge clk or posedge areset) begin
        if (areset) begin
            ghr <= 7'b0;
